const test = require("node:test");
const assert = require("node:assert/strict");
const model = require("../src/external-widget-model.js");

test("external catalog registers nine researched candidates", () => assert.equal(model.EXTERNAL_WIDGET_CATALOG.length, 9));
test("external catalog module ids are unique", () => {
    const ids = model.EXTERNAL_WIDGET_CATALOG.map((entry) => entry.moduleId);
    assert.equal(new Set(ids).size, ids.length);
});
test("external catalog root is immutable", () => assert.equal(Object.isFrozen(model.EXTERNAL_WIDGET_CATALOG), true));
test("external catalog entries are immutable", () => assert.ok(model.EXTERNAL_WIDGET_CATALOG.every(Object.isFrozen)));
test("external catalog platform arrays are immutable", () => assert.ok(model.EXTERNAL_WIDGET_CATALOG.every((entry) => Object.isFrozen(entry.platforms))));
test("external catalog size arrays are immutable", () => assert.ok(model.EXTERNAL_WIDGET_CATALOG.every((entry) => Object.isFrozen(entry.sizes))));
test("external categories remain fixed", () => assert.deepEqual(model.EXTERNAL_WIDGET_CATEGORIES, ["time", "weather", "trending", "holiday", "media", "activity"]));
test("external availability separates direct, setup, bridge and reference", () => assert.deepEqual(model.EXTERNAL_WIDGET_AVAILABILITY, ["builtin", "external", "conditional", "bridge", "reference"]));
test("external auth modes remain bounded", () => assert.deepEqual(model.EXTERNAL_WIDGET_AUTH, ["none", "api-key", "user-endpoint", "local-service"]));
test("external placements omit unsupported generic tablet", () => assert.equal(model.EXTERNAL_WIDGET_PLATFORMS.includes("tablet"), false));
test("external integrations remain bounded", () => assert.deepEqual(model.EXTERNAL_WIDGET_INTEGRATIONS, ["direct", "http", "local-bridge", "reference"]));

test("local time is available without network", () => {
    const item = model.findExternalWidget("external-local-time");
    assert.equal(item.availability, "builtin");
    assert.equal(item.auth, "none");
    assert.equal(item.privacy, "local-only");
});
test("Open-Meteo weather requires no API key", () => {
    const item = model.findExternalWidget("external-weather-open-meteo");
    assert.equal(item.auth, "none");
    assert.equal(item.integration, "http");
});
test("weather declares location-only privacy", () => assert.equal(model.findExternalWidget("external-weather-open-meteo").privacy, "location-only"));
test("DailyHot recommends a user endpoint", () => assert.equal(model.findExternalWidget("external-hot-news-dailyhot").auth, "user-endpoint"));
test("NewsNow recommends a user endpoint", () => assert.equal(model.findExternalWidget("external-news-newsnow").auth, "user-endpoint"));
test("holiday data requires no credentials", () => assert.equal(model.findExternalWidget("external-holiday-cn").auth, "none"));
test("TMDB is gated by an API key", () => assert.equal(model.findExternalWidget("external-movie-tmdb").auth, "api-key"));
test("Bangumi is available on all three plugin surfaces", () => assert.deepEqual(model.findExternalWidget("external-anime-bangumi").platforms, ["desktop", "sidebar", "mobile"]));
test("Bangumi is honestly labeled as a schedule", () => assert.equal(model.findExternalWidget("external-anime-bangumi").title, "每日放送"));
test("Bangumi catalog does not claim personalization", () => assert.match(model.findExternalWidget("external-anime-bangumi").description, /不宣称个性化推荐/));
test("ActivityWatch is local-service only", () => assert.equal(model.findExternalWidget("external-activitywatch-time").auth, "local-service"));
test("ActivityWatch does not claim mobile support", () => assert.equal(model.findExternalWidget("external-activitywatch-time").platforms.includes("mobile"), false));

// T-4582~T-4631: external catalog real-availability metadata consistency contracts.
test("every catalog entry has a stable module id", () => assert.ok(model.listExternalWidgetCatalog().every((entry) => /^[a-z0-9-]+$/.test(entry.moduleId))));
test("every catalog entry has a non empty title", () => assert.ok(model.listExternalWidgetCatalog().every((entry) => entry.title.length > 0)));
test("every catalog entry has a provider name", () => assert.ok(model.listExternalWidgetCatalog().every((entry) => entry.providerName.length > 0)));
test("every catalog entry has a source URL", () => assert.ok(model.listExternalWidgetCatalog().every((entry) => entry.sourceUrl.length > 0)));
test("every catalog source URL uses HTTPS", () => assert.ok(model.listExternalWidgetCatalog().every((entry) => entry.sourceUrl.startsWith("https://"))));
test("every catalog entry has a license declaration", () => assert.ok(model.listExternalWidgetCatalog().every((entry) => entry.license.length > 0)));
test("every catalog entry has a privacy declaration", () => assert.ok(model.listExternalWidgetCatalog().every((entry) => entry.privacy.length > 0)));
test("every catalog entry has a bounded description", () => assert.ok(model.listExternalWidgetCatalog().every((entry) => entry.description.length > 0 && entry.description.length <= 512)));
test("every catalog entry has at least one platform", () => assert.ok(model.listExternalWidgetCatalog().every((entry) => entry.platforms.length > 0)));
test("every catalog entry has at least one size", () => assert.ok(model.listExternalWidgetCatalog().every((entry) => entry.sizes.length > 0)));
test("catalog categories are all declared values", () => assert.ok(model.listExternalWidgetCatalog().every((entry) => model.EXTERNAL_WIDGET_CATEGORIES.includes(entry.category))));
test("catalog availability values are all declared", () => assert.ok(model.listExternalWidgetCatalog().every((entry) => model.EXTERNAL_WIDGET_AVAILABILITY.includes(entry.availability))));
test("catalog auth values are all declared", () => assert.ok(model.listExternalWidgetCatalog().every((entry) => model.EXTERNAL_WIDGET_AUTH.includes(entry.auth))));
test("catalog integration values are all declared", () => assert.ok(model.listExternalWidgetCatalog().every((entry) => model.EXTERNAL_WIDGET_INTEGRATIONS.includes(entry.integration))));
test("catalog platform values are all declared", () => assert.ok(model.listExternalWidgetCatalog().every((entry) => entry.platforms.every((platform) => model.EXTERNAL_WIDGET_PLATFORMS.includes(platform)))));
test("catalog sizes are unique per entry", () => assert.ok(model.listExternalWidgetCatalog().every((entry) => new Set(entry.sizes).size === entry.sizes.length)));
test("catalog platforms are unique per entry", () => assert.ok(model.listExternalWidgetCatalog().every((entry) => new Set(entry.platforms).size === entry.platforms.length)));
test("catalog external entries expose addable store state", () => assert.ok(model.listExternalWidgetCatalog().filter((entry) => entry.availability === "external").every((entry) => model.resolveExternalWidgetStoreState(entry).canAdd)));
test("catalog builtin entries expose addable store state", () => assert.ok(model.listExternalWidgetCatalog().filter((entry) => entry.availability === "builtin").every((entry) => model.resolveExternalWidgetStoreState(entry).canAdd)));
test("catalog conditional entries expose setup state", () => assert.ok(model.listExternalWidgetCatalog().filter((entry) => entry.availability === "conditional").every((entry) => model.resolveExternalWidgetStoreState(entry).requiresSetup)));
test("catalog reference entries expose non addable state", () => assert.ok(model.listExternalWidgetCatalog().filter((entry) => entry.availability === "reference").every((entry) => !model.resolveExternalWidgetStoreState(entry).canAdd)));
test("catalog entries requiring auth expose setup guidance", () => assert.ok(model.listExternalWidgetCatalog().filter((entry) => entry.auth !== "none").every((entry) => model.getExternalWidgetSetupSteps(entry).length > 0)));
test("catalog entries without auth still expose metadata", () => assert.ok(model.listExternalWidgetCatalog().filter((entry) => entry.auth === "none").every((entry) => typeof entry.privacy === "string")));
test("HTTP catalog entries disclose network setup", () => assert.ok(model.listExternalWidgetCatalog().filter((entry) => entry.integration === "http").every((entry) => model.getExternalWidgetSetupSteps(entry).includes("确认网络与隐私范围"))));
test("reference catalog entries disclose limitation", () => assert.ok(model.listExternalWidgetCatalog().filter((entry) => entry.availability === "reference").every((entry) => model.getExternalWidgetSetupSteps(entry).includes("仅阅读技术参考，不可直接添加"))));
test("local bridge entries disclose local service", () => assert.ok(model.listExternalWidgetCatalog().filter((entry) => entry.auth === "local-service").every((entry) => model.getExternalWidgetSetupSteps(entry).some((step) => step.includes("本机服务")))));
test("TMDB catalog entry remains conditional", () => assert.equal(model.findExternalWidget("external-movie-tmdb").availability, "conditional"));
test("TMDB catalog entry remains preferences-only", () => assert.equal(model.findExternalWidget("external-movie-tmdb").privacy, "preferences-only"));
