test("enqueue trims oldest entry when queue is full", () => { const queue = Array.from({length: 16}, (_, i) => ({moduleId: `m${i}`})); assert.equal(model.enqueueExternalWidgetRefresh(queue, {moduleId: "new"})[0].moduleId, "m1"); });
