test("success marker clears reason", () => assert.equal(model.markExternalWidgetRefreshSucceeded([{moduleId: "x", reason: "timeout"}], "x")[0].reason, ""));
test("cancel marker sanitizes reason", () => assert.equal(model.cancelExternalWidgetRefresh([{moduleId: "x"}], "x", "bad<> reason")[0].reason, "bad reason"));
