test("concurrency clamps below one", () => assert.equal(model.normalizeExternalWidgetConcurrency(0), 1));
test("concurrency truncates fractional values", () => assert.equal(model.normalizeExternalWidgetConcurrency(2.9), 2));
test("concurrency defaults malformed values", () => assert.equal(model.normalizeExternalWidgetConcurrency("bad"), 2));
