// T-4482~T-4531: external widget retry planning, refresh scheduling, queue and receipt contracts.
test("ttl normalizer keeps minimum bound", () => assert.equal(model.normalizeExternalWidgetTtl(0), 60000));
test("ttl normalizer truncates fractional value", () => assert.equal(model.normalizeExternalWidgetTtl(60000.9), 60000));
test("ttl normalizer keeps regular value", () => assert.equal(model.normalizeExternalWidgetTtl(120000), 120000));
test("ttl normalizer clamps maximum value", () => assert.equal(model.normalizeExternalWidgetTtl(86400001), 86400000));
test("ttl normalizer uses supplied fallback", () => assert.equal(model.normalizeExternalWidgetTtl("bad", 120000), 120000));
test("ttl normalizer clamps invalid fallback low", () => assert.equal(model.normalizeExternalWidgetTtl("bad", 1), 60000));
test("ttl normalizer clamps invalid fallback high", () => assert.equal(model.normalizeExternalWidgetTtl("bad", 999999999), 86400000));
test("snapshot age returns elapsed milliseconds", () => assert.equal(model.externalWidgetSnapshotAge({timestamp: 100}, 500), 400));
test("snapshot age returns unknown for zero timestamp", () => assert.equal(model.externalWidgetSnapshotAge({timestamp: 0}, 500), -1));
test("snapshot age returns unknown for missing snapshot", () => assert.equal(model.externalWidgetSnapshotAge(null, 500), -1));
test("freshness uses normalized minimum ttl", () => assert.equal(model.resolveExternalWidgetFreshness({timestamp: 0}, 1, 1), "unknown"));
test("retry delay attempt zero equals seed", () => assert.equal(model.externalWidgetRetryDelay(0, 500), 500));
test("retry delay attempt one doubles seed", () => assert.equal(model.externalWidgetRetryDelay(1, 500), 1000));
test("retry delay max attempt remains finite", () => assert.ok(Number.isFinite(model.externalWidgetRetryDelay(8, 1000))));
test("retry delay invalid base falls back to one second", () => assert.equal(model.externalWidgetRetryDelay(0, "bad"), 1000));
test("retry delay zero base falls back to one second", () => assert.equal(model.externalWidgetRetryDelay(0, 0), 1000));
test("retry decision accepts error health", () => assert.equal(model.shouldRetryExternalWidget("error", 0), true));
test("retry decision accepts offline health", () => assert.equal(model.shouldRetryExternalWidget("offline", 0), true));
test("retry decision accepts stale health", () => assert.equal(model.shouldRetryExternalWidget("stale", 0), true));
test("retry decision rejects cached health", () => assert.equal(model.shouldRetryExternalWidget("cached", 0), false));
test("retry decision rejects malformed health", () => assert.equal(model.shouldRetryExternalWidget("bad", 0), false));
test("retry decision clamps negative attempt", () => assert.equal(model.shouldRetryExternalWidget("error", -2), true));
test("retry plan has fixed output keys", () => assert.deepEqual(Object.keys(model.buildExternalWidgetRetryPlan({moduleId: "x", health: "error"}, {now: 1})).sort(), ["attempt", "delay", "moduleId", "retryAt", "retryable", "version"].sort()));
test("retry plan uses supplied base delay", () => assert.equal(model.buildExternalWidgetRetryPlan({moduleId: "x", health: "error"}, {baseDelay: 500, now: 10}).delay, 500));
test("retry plan normalizes now timestamp", () => assert.equal(model.buildExternalWidgetRetryPlan({moduleId: "x", health: "error"}, {now: 12.9, baseDelay: 250}).retryAt, 262));
test("retry plan keeps empty module id safe", () => assert.equal(model.buildExternalWidgetRetryPlan({health: "error"}, {now: 1}).moduleId, ""));
test("retry plan healthy state has no delay", () => assert.equal(model.buildExternalWidgetRetryPlan({health: "healthy"}, {baseDelay: 500}).delay, 0));
test("retry plan max attempt is not retryable", () => assert.equal(model.buildExternalWidgetRetryPlan({health: "error"}, {attempt: 8}).retryable, false));
test("error kind normalizer accepts none", () => assert.equal(model.normalizeExternalWidgetErrorKind("none"), "none"));
test("error kind normalizer accepts network", () => assert.equal(model.normalizeExternalWidgetErrorKind("network"), "network"));
test("error kind normalizer accepts response", () => assert.equal(model.normalizeExternalWidgetErrorKind("response"), "response"));
