test("refresh state normalizer accepts succeeded", () => assert.equal(model.normalizeExternalWidgetRefreshState("succeeded"), "succeeded"));
test("refresh state normalizer accepts failed", () => assert.equal(model.normalizeExternalWidgetRefreshState("failed"), "failed"));
test("refresh state normalizer accepts cancelled", () => assert.equal(model.normalizeExternalWidgetRefreshState("cancelled"), "cancelled"));
test("refresh state normalizer accepts skipped", () => assert.equal(model.normalizeExternalWidgetRefreshState("skipped"), "skipped"));
test("priority normalizer defaults malformed value", () => assert.equal(model.normalizeExternalWidgetPriority("bad"), 1));
test("priority normalizer clamps upper bound", () => assert.equal(model.normalizeExternalWidgetPriority(99), 3));
test("priority normalizer clamps lower bound", () => assert.equal(model.normalizeExternalWidgetPriority(-99), 0));
test("refresh entry normalizer trims module id", () => assert.equal(model.normalizeExternalWidgetRefreshEntry({moduleId: " x "}).moduleId, "x"));
test("refresh entry normalizer truncates requested time", () => assert.equal(model.normalizeExternalWidgetRefreshEntry({moduleId: "x", requestedAt: 5.9}).requestedAt, 5));
test("refresh entry normalizer clamps attempt", () => assert.equal(model.normalizeExternalWidgetRefreshEntry({moduleId: "x", attempt: 99}).attempt, 8));
test("refresh entry normalizer sanitizes reason", () => assert.equal(model.normalizeExternalWidgetRefreshEntry({moduleId: "x", reason: "bad<>"}).reason, "bad"));
test("refresh queue normalizer preserves input order", () => assert.deepEqual(model.normalizeExternalWidgetRefreshQueue([{moduleId: "a"}, {moduleId: "b"}]).map((x) => x.moduleId), ["a", "b"]));
test("refresh queue normalizer caps at sixteen entries", () => assert.equal(model.normalizeExternalWidgetRefreshQueue(Array.from({length: 20}, (_, i) => ({moduleId: `m${i}`}))).length, 16));
test("enqueue defaults requested time from now", () => assert.equal(model.enqueueExternalWidgetRefresh([], {moduleId: "x"}, 123)[0].requestedAt, 123));
test("enqueue sets queued state over supplied state", () => assert.equal(model.enqueueExternalWidgetRefresh([], {moduleId: "x", state: "running"})[0].state, "queued"));
test("enqueue preserves higher existing priority", () => assert.equal(model.enqueueExternalWidgetRefresh([{moduleId: "x", priority: 3}], {moduleId: "x", priority: 1})[0].priority, 3));
test("enqueue updates duplicate requested time", () => assert.equal(model.enqueueExternalWidgetRefresh([{moduleId: "x", requestedAt: 1}], {moduleId: "x", requestedAt: 2})[0].requestedAt, 2));
test("enqueue returns defensive queue objects", () => { const input = [{moduleId: "x"}]; const output = model.enqueueExternalWidgetRefresh(input, {moduleId: "y"}); assert.notEqual(output, input); });
test("dequeue selects highest priority before age", () => assert.equal(model.dequeueExternalWidgetRefresh([{moduleId: "old", state: "queued", priority: 1, requestedAt: 1}, {moduleId: "new", state: "queued", priority: 2, requestedAt: 99}]).entry.moduleId, "new"));
test("dequeue marks selected entry running", () => assert.equal(model.dequeueExternalWidgetRefresh([{moduleId: "x", state: "queued"}]).entry.state, "running"));
test("dequeue removes selected module only", () => assert.deepEqual(model.dequeueExternalWidgetRefresh([{moduleId: "x", state: "queued"}, {moduleId: "y", state: "running"}]).queue.map((x) => x.moduleId), ["y"]));
test("dequeue leaves queue unchanged when no queued item", () => assert.equal(model.dequeueExternalWidgetRefresh([{moduleId: "x", state: "running"}]).queue.length, 1));
test("update entry changes priority", () => assert.equal(model.updateExternalWidgetRefreshEntry([{moduleId: "x"}], "x", {priority: 3})[0].priority, 3));
test("update entry changes attempt", () => assert.equal(model.updateExternalWidgetRefreshEntry([{moduleId: "x"}], "x", {attempt: 4})[0].attempt, 4));
test("update entry ignores primitive patch", () => assert.equal(model.updateExternalWidgetRefreshEntry([{moduleId: "x", state: "queued"}], "x", "bad")[0].state, "queued"));
test("update entry trims module id key", () => assert.equal(model.updateExternalWidgetRefreshEntry([{moduleId: "x"}], " x ", {state: "running"})[0].state, "running"));
test("success marker sets succeeded state", () => assert.equal(model.markExternalWidgetRefreshSucceeded([{moduleId: "x", state: "running"}], "x")[0].state, "succeeded"));
test("success marker clears prior reason", () => assert.equal(model.markExternalWidgetRefreshSucceeded([{moduleId: "x", reason: "fail"}], "x")[0].reason, ""));
test("failure marker increments from zero", () => assert.equal(model.markExternalWidgetRefreshFailed([{moduleId: "x", attempt: 0}], "x")[0].attempt, 1));
test("failure marker caps increment at retry max", () => assert.equal(model.markExternalWidgetRefreshFailed([{moduleId: "x", attempt: 8}], "x")[0].attempt, 8));
test("failure marker sanitizes reason", () => assert.equal(model.markExternalWidgetRefreshFailed([{moduleId: "x"}], "x", "bad<>")[0].reason, "bad"));
test("cancel marker uses default reason", () => assert.equal(model.cancelExternalWidgetRefresh([{moduleId: "x"}], "x")[0].reason, "cancelled"));
test("cancel marker preserves custom reason", () => assert.equal(model.cancelExternalWidgetRefresh([{moduleId: "x"}], "x", "user")[0].reason, "user"));
test("remove entry trims module id key", () => assert.deepEqual(model.removeExternalWidgetRefresh([{moduleId: "x"}], " x "), []));
test("remove entry keeps other modules", () => assert.deepEqual(model.removeExternalWidgetRefresh([{moduleId: "x"}, {moduleId: "y"}], "x").map((x) => x.moduleId), ["y"]));
test("state counts count queued and running", () => { const counts = model.countExternalWidgetRefreshStates([{moduleId: "a", state: "queued"}, {moduleId: "b", state: "running"}]); assert.deepEqual({queued: counts.queued, running: counts.running}, {queued: 1, running: 1}); });
test("state counts normalize unknown state to idle", () => assert.equal(model.countExternalWidgetRefreshStates([{moduleId: "x", state: "bad"}]).idle, 1));
test("concurrency normalizer accepts four", () => assert.equal(model.normalizeExternalWidgetConcurrency(4), 4));
test("concurrency normalizer clamps above four", () => assert.equal(model.normalizeExternalWidgetConcurrency(99), 4));
test("concurrency normalizer clamps below one", () => assert.equal(model.normalizeExternalWidgetConcurrency(-1), 1));
test("batch planner returns fixed shape", () => assert.deepEqual(Object.keys(model.planExternalWidgetRefreshBatch([], 2)).sort(), ["entries", "queue"]));
test("batch planner handles concurrency four", () => assert.equal(model.planExternalWidgetRefreshBatch(Array.from({length: 6}, (_, i) => ({moduleId: `m${i}`, state: "queued"})), 4).entries.length, 4));
test("batch planner keeps terminal entries in remainder", () => assert.equal(model.planExternalWidgetRefreshBatch([{moduleId: "done", state: "succeeded"}, {moduleId: "q", state: "queued"}], 1).queue[0].moduleId, "done"));
test("batch summary has fixed keys", () => assert.deepEqual(Object.keys(model.summarizeExternalWidgetRefreshBatch([], [])).sort(), ["cancelled", "failed", "queued", "running", "succeeded", "total"].sort()));
test("batch summary counts succeeded entries", () => assert.equal(model.summarizeExternalWidgetRefreshBatch([{moduleId: "x", state: "succeeded"}]).succeeded, 1));
test("batch summary counts queued remainder", () => assert.equal(model.summarizeExternalWidgetRefreshBatch([], [{moduleId: "x", state: "queued"}]).queued, 1));
test("receipt has fixed keys", () => assert.deepEqual(Object.keys(model.buildExternalWidgetRefreshReceipt({moduleId: "x"})).sort(), ["attempt", "moduleId", "reason", "state"].sort()));
test("receipt normalizes reason punctuation", () => assert.equal(model.buildExternalWidgetRefreshReceipt({moduleId: "x"}, {reason: "bad<>"}).reason, "bad"));
test("receipt merge handles non array", () => assert.deepEqual(model.mergeExternalWidgetRefreshReceipts(null), []));
test("receipt merge removes empty module ids", () => assert.deepEqual(model.mergeExternalWidgetRefreshReceipts([{}, {moduleId: "x"}]).map((x) => x.moduleId), ["x"]));
test("receipt merge sorts module ids", () => assert.deepEqual(model.mergeExternalWidgetRefreshReceipts([{moduleId: "b"}, {moduleId: "a"}]).map((x) => x.moduleId), ["a", "b"]));
test("schedule decision accepts expired healthy snapshot", () => assert.equal(model.shouldScheduleExternalWidgetRefresh({moduleId: "x", health: "healthy", timestamp: 1}, 60000, 70000), true));
test("schedule decision accepts error before ttl", () => assert.equal(model.shouldScheduleExternalWidgetRefresh({moduleId: "x", health: "error", timestamp: 69000}, 60000, 70000), true));
test("schedule decision rejects fresh healthy snapshot", () => assert.equal(model.shouldScheduleExternalWidgetRefresh({moduleId: "x", health: "healthy", timestamp: 69000}, 60000, 70000), false));
test("clear queue keeps all running entries", () => assert.deepEqual(model.clearExternalWidgetRefreshQueue([{moduleId: "a", state: "running"}, {moduleId: "b", state: "running"}]).map((x) => x.moduleId), ["a", "b"]));
test("clear queue returns empty for terminal entries", () => assert.deepEqual(model.clearExternalWidgetRefreshQueue([{moduleId: "a", state: "succeeded"}, {moduleId: "b", state: "failed"}]), []));

// T-4682~T-4731: external widget model immutability, defensive copies and side-effect isolation.
test("all exported catalog enums are frozen", () => assert.ok([model.EXTERNAL_WIDGET_CATEGORIES, model.EXTERNAL_WIDGET_AVAILABILITY, model.EXTERNAL_WIDGET_AUTH, model.EXTERNAL_WIDGET_PLATFORMS, model.EXTERNAL_WIDGET_INTEGRATIONS, model.EXTERNAL_WIDGET_HEALTH, model.EXTERNAL_WIDGET_ACTIONS, model.EXTERNAL_WIDGET_FRESHNESS, model.EXTERNAL_WIDGET_ERROR_KINDS, model.EXTERNAL_WIDGET_REFRESH_STATES].every(Object.isFrozen)));
test("catalog enum mutation cannot change category values", () => { const before = model.EXTERNAL_WIDGET_CATEGORIES[0]; try { model.EXTERNAL_WIDGET_CATEGORIES[0] = "changed"; } catch (_) {} assert.equal(model.EXTERNAL_WIDGET_CATEGORIES[0], before); });
test("catalog enum mutation cannot append availability", () => { const length = model.EXTERNAL_WIDGET_AVAILABILITY.length; try { model.EXTERNAL_WIDGET_AVAILABILITY.push("new"); } catch (_) {} assert.equal(model.EXTERNAL_WIDGET_AVAILABILITY.length, length); });
test("catalog root rejects replacement entries", () => { const before = model.EXTERNAL_WIDGET_CATALOG[0].moduleId; try { model.EXTERNAL_WIDGET_CATALOG[0] = {}; } catch (_) {} assert.equal(model.EXTERNAL_WIDGET_CATALOG[0].moduleId, before); });
test("catalog entry rejects title mutation", () => { const entry = model.EXTERNAL_WIDGET_CATALOG[0]; const before = entry.title; try { entry.title = "changed"; } catch (_) {} assert.equal(entry.title, before); });
test("catalog entry rejects platform append", () => { const entry = model.EXTERNAL_WIDGET_CATALOG[0]; const length = entry.platforms.length; try { entry.platforms.push("tablet"); } catch (_) {} assert.equal(entry.platforms.length, length); });
test("catalog entry rejects size replacement", () => { const entry = model.EXTERNAL_WIDGET_CATALOG[0]; const before = entry.sizes[0]; try { entry.sizes[0] = "huge"; } catch (_) {} assert.equal(entry.sizes[0], before); });
test("catalog listing returns a fresh array each time", () => assert.notEqual(model.listExternalWidgetCatalog(), model.listExternalWidgetCatalog()));
test("catalog listing entries are detached from catalog entries", () => { const listed = model.listExternalWidgetCatalog(); assert.notEqual(listed[0], model.EXTERNAL_WIDGET_CATALOG[0]); });
test("catalog listing platform arrays are detached", () => { const listed = model.listExternalWidgetCatalog(); assert.notEqual(listed[0].platforms, model.EXTERNAL_WIDGET_CATALOG[0].platforms); });
test("catalog listing size arrays are detached", () => { const listed = model.listExternalWidgetCatalog(); assert.notEqual(listed[0].sizes, model.EXTERNAL_WIDGET_CATALOG[0].sizes); });
test("catalog listing nested mutation stays local", () => { const listed = model.listExternalWidgetCatalog(); listed[0].platforms.push("tablet"); assert.equal(model.listExternalWidgetCatalog()[0].platforms.includes("tablet"), false); });
test("find returns a detached entry", () => { const found = model.findExternalWidget("external-local-time"); assert.notEqual(found, model.EXTERNAL_WIDGET_CATALOG[0]); });
test("find nested mutation does not pollute catalog", () => { const found = model.findExternalWidget("external-local-time"); found.sizes.push("huge"); assert.equal(model.findExternalWidget("external-local-time").sizes.includes("huge"), false); });
test("find trims module id without mutating input string", () => { const id = " external-local-time "; assert.equal(model.findExternalWidget(id).moduleId, "external-local-time"); assert.equal(id, " external-local-time "); });
test("normalizer does not mutate source title", () => { const source = {moduleId: "x", title: "  Title  "}; model.normalizeExternalWidget(source); assert.equal(source.title, "  Title  "); });
test("normalizer does not mutate source platforms", () => { const platforms = ["desktop", "mobile"]; const source = {platforms}; model.normalizeExternalWidget(source); assert.deepEqual(platforms, ["desktop", "mobile"]); });
test("normalizer does not mutate source sizes", () => { const sizes = [" small ", "medium"]; const source = {sizes}; model.normalizeExternalWidget(source); assert.deepEqual(sizes, [" small ", "medium"]); });
test("normalizer returns a fresh platforms array", () => { const platforms = ["desktop"]; const normalized = model.normalizeExternalWidget({platforms}); assert.notEqual(normalized.platforms, platforms); });
test("normalizer returns a fresh sizes array", () => { const sizes = ["small"]; const normalized = model.normalizeExternalWidget({sizes}); assert.notEqual(normalized.sizes, sizes); });
test("filter does not mutate source entries", () => { const source = [{moduleId: "x", title: "X", platforms: ["desktop"]}]; model.filterExternalWidgets(source, {query: "x"}); assert.deepEqual(source, [{moduleId: "x", title: "X", platforms: ["desktop"]}]); });
test("filter returns entries detached from source", () => { const source = [{moduleId: "x", title: "X", platforms: ["desktop"]}]; const result = model.filterExternalWidgets(source); result[0].platforms.push("mobile"); assert.deepEqual(source[0].platforms, ["desktop"]); });
test("filter handles frozen input without mutation", () => { const source = Object.freeze([{moduleId: "x", title: "X", platforms: Object.freeze(["desktop"])}]); assert.equal(model.filterExternalWidgets(source).length, 1); });
test("summary does not mutate source entries", () => { const source = [{moduleId: "x", title: "X", platforms: ["desktop"]}]; model.summarizeExternalWidgets(source); assert.deepEqual(source[0].platforms, ["desktop"]); });
test("summary ignores later mutation of returned data", () => { const source = [{moduleId: "x", availability: "external"}]; const result = model.summarizeExternalWidgets(source); source[0].availability = "reference"; assert.equal(result.external, 1); });
test("group does not mutate source entries", () => { const source = [{moduleId: "x", category: "media", platforms: ["desktop"]}]; model.groupExternalWidgets(source); assert.deepEqual(source[0].platforms, ["desktop"]); });
test("group returns detached group entries", () => { const source = [{moduleId: "x", category: "media"}]; const groups = model.groupExternalWidgets(source); groups.get("media")[0].title = "changed"; assert.equal(source[0].title, undefined); });
test("sort does not mutate source order", () => { const source = [{moduleId: "b", title: "B"}, {moduleId: "a", title: "A"}]; model.sortExternalWidgetCatalog(source); assert.deepEqual(source.map((x) => x.moduleId), ["b", "a"]); });
test("sort returns a new array", () => { const source = [{moduleId: "x", title: "X"}]; assert.notEqual(model.sortExternalWidgetCatalog(source), source); });
test("sort returns detached entries", () => { const source = [{moduleId: "x", title: "X"}]; const result = model.sortExternalWidgetCatalog(source); result[0].title = "changed"; assert.equal(source[0].title, "X"); });
test("state list does not mutate entry input", () => { const source = [{moduleId: "x", availability: "conditional"}]; model.normalizeExternalWidgetStateList(source, {configured: true}); assert.equal(source[0].availability, "conditional"); });
test("state list returns detached state objects", () => { const source = [{moduleId: "x", availability: "external"}]; const result = model.normalizeExternalWidgetStateList(source); result[0].status = "changed"; assert.equal(source[0].status, undefined); });
test("snapshot builder does not mutate entry", () => { const entry = {moduleId: "x", availability: "external"}; model.buildExternalWidgetSnapshot(entry, {health: "healthy"}); assert.deepEqual(entry, {moduleId: "x", availability: "external"}); });
test("snapshot builder does not mutate options", () => { const options = {health: "healthy", timestamp: 42}; model.buildExternalWidgetSnapshot({moduleId: "x"}, options); assert.deepEqual(options, {health: "healthy", timestamp: 42}); });
test("snapshot builder returns independent object", () => { const entry = {moduleId: "x"}; const result = model.buildExternalWidgetSnapshot(entry); result.moduleId = "changed"; assert.equal(entry.moduleId, "x"); });
test("snapshot normalizer does not mutate source", () => { const source = {moduleId: "x", health: "healthy"}; model.normalizeExternalWidgetSnapshot(source); assert.deepEqual(source, {moduleId: "x", health: "healthy"}); });
test("snapshot serializer does not mutate source", () => { const source = {moduleId: "x", health: "healthy"}; model.serializeExternalWidgetSnapshot(source); assert.deepEqual(source, {moduleId: "x", health: "healthy"}); });
test("snapshot parser returns a fresh object", () => { const first = model.parseExternalWidgetSnapshot('{"version":1,"moduleId":"x","health":"healthy","action":"add"}'); const second = model.parseExternalWidgetSnapshot('{"version":1,"moduleId":"x","health":"healthy","action":"add"}'); assert.notEqual(first, second); });
test("history normalizer does not mutate source snapshots", () => { const source = [{moduleId: "x", health: "healthy"}]; model.normalizeExternalWidgetHistory(source); assert.deepEqual(source, [{moduleId: "x", health: "healthy"}]); });
test("history normalizer returns detached snapshots", () => { const source = [{moduleId: "x", health: "healthy"}]; const result = model.normalizeExternalWidgetHistory(source); result[0].health = "error"; assert.equal(source[0].health, "healthy"); });
test("append history does not mutate original history", () => { const history = [{moduleId: "x"}]; model.appendExternalWidgetSnapshot(history, {moduleId: "y"}); assert.deepEqual(history, [{moduleId: "x"}]); });
test("trim history does not mutate original array", () => { const history = [{moduleId: "a"}, {moduleId: "b"}]; model.trimExternalWidgetHistory(history, 1); assert.equal(history.length, 2); });
test("history serialization does not mutate history", () => { const history = [{moduleId: "x", health: "healthy"}]; model.serializeExternalWidgetHistory(history); assert.deepEqual(history, [{moduleId: "x", health: "healthy"}]); });
test("queue normalizer does not mutate source queue", () => { const queue = [{moduleId: "x", state: "queued"}]; model.normalizeExternalWidgetRefreshQueue(queue); assert.deepEqual(queue, [{moduleId: "x", state: "queued"}]); });
test("queue normalizer returns detached entries", () => { const queue = [{moduleId: "x", state: "queued"}]; const result = model.normalizeExternalWidgetRefreshQueue(queue); result[0].state = "failed"; assert.equal(queue[0].state, "queued"); });
test("enqueue does not mutate original queue", () => { const queue = [{moduleId: "x", state: "queued"}]; model.enqueueExternalWidgetRefresh(queue, {moduleId: "y"}, 10); assert.deepEqual(queue, [{moduleId: "x", state: "queued"}]); });
test("dequeue does not mutate original queue", () => { const queue = [{moduleId: "x", state: "queued"}]; model.dequeueExternalWidgetRefresh(queue); assert.deepEqual(queue, [{moduleId: "x", state: "queued"}]); });
test("update queue does not mutate original entries", () => { const queue = [{moduleId: "x", state: "queued"}]; model.updateExternalWidgetRefreshEntry(queue, "x", {state: "running"}); assert.equal(queue[0].state, "queued"); });
test("batch planner does not mutate original queue", () => { const queue = [{moduleId: "x", state: "queued"}]; model.planExternalWidgetRefreshBatch(queue, 1); assert.equal(queue[0].state, "queued"); });
test("receipt merge does not mutate source receipts", () => { const receipts = [{moduleId: "x", ok: true}]; model.mergeExternalWidgetRefreshReceipts(receipts); assert.deepEqual(receipts, [{moduleId: "x", ok: true}]); });
test("display selector does not mutate previous snapshot", () => { const previous = {moduleId: "x", health: "healthy", timestamp: 1}; model.selectExternalWidgetDisplaySnapshot(previous, {moduleId: "x", health: "error", timestamp: 2}); assert.deepEqual(previous, {moduleId: "x", health: "healthy", timestamp: 1}); });
test("display selector does not mutate current snapshot", () => { const current = {moduleId: "x", health: "error", reason: "timeout", timestamp: 2}; model.selectExternalWidgetDisplaySnapshot({moduleId: "x", health: "healthy", timestamp: 1}, current); assert.deepEqual(current, {moduleId: "x", health: "error", reason: "timeout", timestamp: 2}); });
test("setup steps do not mutate entry", () => { const entry = {moduleId: "x", auth: "api-key", integration: "http"}; model.getExternalWidgetSetupSteps(entry); assert.deepEqual(entry, {moduleId: "x", auth: "api-key", integration: "http"}); });
test("diagnostic state summary does not mutate states", () => { const states = [{status: "ready", canAdd: true}]; model.summarizeExternalWidgetStates(states); assert.deepEqual(states, [{status: "ready", canAdd: true}]); });
test("snapshot diff does not mutate either input", () => { const previous = {moduleId: "x", health: "healthy"}; const current = {moduleId: "x", health: "error"}; model.diffExternalWidgetSnapshots(previous, current); assert.deepEqual(previous, {moduleId: "x", health: "healthy"}); assert.deepEqual(current, {moduleId: "x", health: "error"}); });
test("transition builder does not mutate either input", () => { const previous = {moduleId: "x", health: "healthy"}; const current = {moduleId: "x", health: "healthy"}; model.buildExternalWidgetTransition(previous, current); assert.deepEqual(previous, {moduleId: "x", health: "healthy"}); assert.deepEqual(current, {moduleId: "x", health: "healthy"}); });

// T-4732~T-4787: external widget persistence compatibility, malformed-input and boundary contracts.
test("snapshot serialization emits only canonical keys", () => assert.deepEqual(Object.keys(JSON.parse(model.serializeExternalWidgetSnapshot({moduleId: "x", extra: true}))).sort(), ["action", "health", "moduleId", "reason", "status", "timestamp", "version"].sort()));
test("snapshot serialization strips unknown fields", () => assert.equal(JSON.parse(model.serializeExternalWidgetSnapshot({moduleId: "x", extra: true})).extra, undefined));
test("snapshot serialization normalizes invalid action", () => assert.equal(JSON.parse(model.serializeExternalWidgetSnapshot({moduleId: "x", action: "unsafe"})).action, "learn-more"));
test("snapshot parser wrong version returns canonical empty shape", () => assert.deepEqual(Object.keys(model.parseExternalWidgetSnapshot('{"version":99,"moduleId":"x"}')).sort(), ["action", "health", "moduleId", "reason", "status", "timestamp", "version"].sort()));
test("snapshot parser malformed object returns empty module", () => assert.equal(model.parseExternalWidgetSnapshot('{"version":1,"moduleId":null}').moduleId, ""));
test("snapshot parser array returns safe empty snapshot", () => assert.equal(model.parseExternalWidgetSnapshot("[]").moduleId, ""));
test("snapshot parser primitive JSON returns safe empty snapshot", () => assert.equal(model.parseExternalWidgetSnapshot("42").moduleId, ""));
test("snapshot parser ignores unknown fields", () => assert.equal(model.parseExternalWidgetSnapshot('{"version":1,"moduleId":"x","extra":"drop"}').extra, undefined));
test("snapshot parser truncates fractional timestamp", () => assert.equal(model.parseExternalWidgetSnapshot('{"version":1,"moduleId":"x","health":"healthy","action":"add","timestamp":8.9}').timestamp, 8));
test("snapshot parser rejects oversized module id", () => assert.equal(model.parseExternalWidgetSnapshot(`{"version":1,"moduleId":"${"x".repeat(120)}","health":"healthy","action":"add"}`).moduleId, ""));
test("history serialization emits fixed envelope keys", () => assert.deepEqual(Object.keys(JSON.parse(model.serializeExternalWidgetHistory([{moduleId: "x"}]))).sort(), ["snapshots", "version"]));
test("history serialization caps snapshots at sixteen", () => assert.equal(JSON.parse(model.serializeExternalWidgetHistory(Array.from({length: 20}, (_, i) => ({moduleId: `m${i}`})))).snapshots.length, 16));
test("history parser wrong version returns empty list", () => assert.deepEqual(model.parseExternalWidgetHistory('{"version":99,"snapshots":[{"moduleId":"x"}]}'), []));
test("history parser non-array snapshots returns empty list", () => assert.deepEqual(model.parseExternalWidgetHistory('{"version":1,"snapshots":{}}'), []));
test("history parser caps oversized record list", () => assert.equal(model.parseExternalWidgetHistory(JSON.stringify({version: 1, snapshots: Array.from({length: 20}, (_, i) => ({moduleId: `m${i}`}))})).length, 16));
test("history normalizer keeps newest bounded records", () => assert.deepEqual(model.normalizeExternalWidgetHistory(Array.from({length: 18}, (_, i) => ({moduleId: `m${i}`}))).map((x) => x.moduleId), Array.from({length: 16}, (_, i) => `m${i + 2}`)));
test("history normalizer canonicalizes health", () => assert.equal(model.normalizeExternalWidgetHistory([{moduleId: "x", health: "invalid"}])[0].health, "unknown"));
test("latest snapshot returns a detached record", () => { const history = [{moduleId: "x", health: "healthy"}]; const latest = model.latestExternalWidgetSnapshot(history); latest.health = "error"; assert.equal(history[0].health, "healthy"); });
test("latest snapshot trims requested module id", () => assert.equal(model.latestExternalWidgetSnapshot([{moduleId: "x"}], " x ").moduleId, "x"));
test("latest snapshot without key uses final normalized record", () => assert.equal(model.latestExternalWidgetSnapshot([{moduleId: "a"}, {moduleId: "b"}]).moduleId, "b"));
test("history selection returns detached records", () => { const history = [{moduleId: "x", health: "stale"}]; const selected = model.selectExternalWidgetHistory(history, "stale"); selected[0].health = "error"; assert.equal(history[0].health, "stale"); });
test("history selection caps limit at history maximum", () => assert.equal(model.selectExternalWidgetHistory(Array.from({length: 20}, (_, i) => ({moduleId: `m${i}`, health: "stale"})), "stale", 99).length, 16));
test("history summary includes every declared health counter", () => assert.deepEqual(Object.keys(model.summarizeExternalWidgetHistory([]).counts).sort(), model.EXTERNAL_WIDGET_HEALTH.slice().sort()));
test("history summary latest is detached", () => { const summary = model.summarizeExternalWidgetHistory([{moduleId: "x", health: "healthy"}]); summary.latest.health = "error"; assert.equal(model.summarizeExternalWidgetHistory([{moduleId: "x", health: "healthy"}]).latest.health, "healthy"); });
test("snapshot merge ignores null and primitive values", () => assert.deepEqual(model.mergeExternalWidgetSnapshots(null, "bad", {moduleId: "x"}).map((x) => x.moduleId), ["x"]));
test("snapshot merge tie uses later source record", () => assert.equal(model.mergeExternalWidgetSnapshots([{moduleId: "x", status: "old", timestamp: 4}], [{moduleId: "x", status: "new", timestamp: 4}])[0].status, "new"));
test("snapshot merge drops records without module ids", () => assert.deepEqual(model.mergeExternalWidgetSnapshots([{health: "healthy"}, {moduleId: "x"}]).map((x) => x.moduleId), ["x"]));
test("snapshot merge returns detached records", () => { const input = {moduleId: "x", health: "healthy"}; const merged = model.mergeExternalWidgetSnapshots(input); merged[0].health = "error"; assert.equal(input.health, "healthy"); });
test("snapshot diff normalizes malformed snapshots", () => assert.equal(model.diffExternalWidgetSnapshots(null, {moduleId: "x"}).moduleId, "x"));
test("transition exposes fixed diff keys", () => assert.deepEqual(Object.keys(model.buildExternalWidgetTransition({moduleId: "x"}, {moduleId: "x"})).sort(), ["actionChanged", "changed", "healthChanged", "moduleId", "reasonChanged", "statusChanged", "type"].sort()));
test("timestamp normalizer uses nonnegative fallback", () => assert.equal(model.normalizeExternalWidgetTimestamp("bad", -4), 0));
test("timestamp normalizer preserves finite fallback", () => assert.equal(model.normalizeExternalWidgetTimestamp("bad", 99999999999999), 99999999999999));
test("timestamp normalizer truncates finite values", () => assert.equal(model.normalizeExternalWidgetTimestamp(12.99), 12));
test("ttl normalizer clamps fractional minimum", () => assert.equal(model.normalizeExternalWidgetTtl(60000.9), 60000));
test("ttl normalizer clamps supplied fallback maximum", () => assert.equal(model.normalizeExternalWidgetTtl("bad", 999999999), 86400000));
test("snapshot age never becomes negative", () => assert.equal(model.externalWidgetSnapshotAge({timestamp: 5000}, 1000), 0));
test("freshness marks middle age as aging", () => assert.equal(model.resolveExternalWidgetFreshness({timestamp: 1000}, 60000, 61001), "aging"));
test("retry delay clamps base below minimum", () => assert.equal(model.externalWidgetRetryDelay(0, 1), 250));
test("retry delay caps at five minutes", () => assert.equal(model.externalWidgetRetryDelay(8, 30000), 300000));
test("retry plan has deterministic defaults", () => assert.deepEqual(model.buildExternalWidgetRetryPlan({moduleId: "x", health: "healthy"}, {now: 10}), {version: 1, moduleId: "x", attempt: 0, retryable: false, delay: 0, retryAt: 0}));
test("retry plan does not mutate snapshot input", () => { const snapshot = {moduleId: "x", health: "error", timestamp: 1}; model.buildExternalWidgetRetryPlan(snapshot, {now: 10}); assert.deepEqual(snapshot, {moduleId: "x", health: "error", timestamp: 1}); });
test("error classifier strips control characters safely", () => assert.equal(model.classifyExternalWidgetError("network\nfailure"), "network"));
test("error classifier maps arbitrary text to unknown", () => assert.equal(model.classifyExternalWidgetError("something unexpected"), "unknown"));
test("error classifier treats null as none", () => assert.equal(model.classifyExternalWidgetError(null), "none"));
test("refresh entry exposes canonical keys", () => assert.deepEqual(Object.keys(model.normalizeExternalWidgetRefreshEntry({moduleId: "x"})).sort(), ["attempt", "moduleId", "priority", "reason", "requestedAt", "state"].sort()));
test("refresh entry primitive input is safe", () => assert.equal(model.normalizeExternalWidgetRefreshEntry("bad").moduleId, ""));
test("refresh queue keeps first sixteen normalized entries", () => assert.deepEqual(model.normalizeExternalWidgetRefreshQueue(Array.from({length: 20}, (_, i) => ({moduleId: `m${i}`}))).map((x) => x.moduleId), Array.from({length: 16}, (_, i) => `m${i}`)));
test("refresh queue drops entries without ids", () => assert.deepEqual(model.normalizeExternalWidgetRefreshQueue([{}, {moduleId: "x"}]).map((x) => x.moduleId), ["x"]));
test("refresh receipt ignores extra result fields", () => assert.equal(model.buildExternalWidgetRefreshReceipt({moduleId: "x"}, {ok: true, extra: true}).extra, undefined));
test("refresh receipt does not mutate result input", () => { const result = {ok: false, reason: "timeout"}; model.buildExternalWidgetRefreshReceipt({moduleId: "x"}, result); assert.deepEqual(result, {ok: false, reason: "timeout"}); });
test("refresh batch summary exposes bounded counters", () => assert.deepEqual(Object.keys(model.summarizeExternalWidgetRefreshBatch([], [])).sort(), ["cancelled", "failed", "queued", "running", "succeeded", "total"].sort()));
test("state summary ignores primitive states", () => assert.equal(model.summarizeExternalWidgetStates([null, "bad", 1]).total, 0));
test("state description keeps setup action precedence", () => assert.equal(model.describeExternalWidgetStoreState({moduleId: "x", availability: "conditional"}, {configured: false, health: "error"}).action, "configure"));
test("state description keeps reference action precedence", () => assert.equal(model.describeExternalWidgetStoreState({moduleId: "x", availability: "reference"}, {health: "error"}).action, "learn-more"));
test("state description sanitizes reason output", () => assert.equal(model.describeExternalWidgetStoreState({moduleId: "x"}, {reason: "bad<>"}).reason, "bad"));
test("privacy resolver rejects object values", () => assert.equal(model.resolveExternalWidgetPrivacyLevel({}), "unknown"));
